// quote types: ocr (text found on a leaf; text may be an array of fragments, all on the leaf), image (read from a page image; ocr_check says what the OCR shows),
// web (text of a cached web page), site (a value at a path in a repo JSON file), ref (an observation in weather_by_day.json)
const ocr = (id, source, key, page, text, extra = {}) => ({ id, type: 'ocr', source, ia: IA[key].ia, kind: IA[key].kind, page, text, ...extra });
const img = (id, source, key, page, text, reading, ocr_check, extra = {}) => ({ id, type: 'image', source, ia: IA[key].ia, kind: IA[key].kind, page, text, reading, ocr_check, ...extra });
const web = (id, source, text, extra = {}) => ({ id, type: 'web', source, text, ...extra });

